// Package auth checks the Bearer tokens of the devices.
//
// The server only knows the SHA-256 hashes of the tokens, each with a label (e.g. the name of
// the device) that is logged instead of the token. Tokens are random strings generated by
// `route-gateway token` (or scripts/new-token.sh); the plain token is shown once and entered in
// the app.
//
// Token file format, one token per line, '#' starts a comment:
//
//	<label> sha256:<64 hex digits>
package auth

import (
	"bufio"
	"crypto/rand"
	"crypto/sha256"
	"crypto/subtle"
	"encoding/base64"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"net/http"
	"os"
	"regexp"
	"strings"
	"sync/atomic"
)

// MinTokenLength is the minimum length of a presented token. Generated tokens are longer
// (43 characters, 256 bits); shorter ones are rejected without comparing.
const MinTokenLength = 20

// MaxTokenLength bounds the work spent on a presented token.
const MaxTokenLength = 256

var reLabel = regexp.MustCompile(`^[A-Za-z0-9._-]{1,32}$`)

type entry struct {
	label string
	hash  [sha256.Size]byte
}

// Store holds the token hashes. It is safe for concurrent use; Replace swaps the set atomically
// (e.g. after the token file changed).
type Store struct {
	entries atomic.Pointer[[]entry]
}

// NewStore returns an empty store (every token is rejected).
func NewStore() *Store {
	s := &Store{}
	s.entries.Store(&[]entry{})
	return s
}

// Len returns the number of known tokens.
func (s *Store) Len() int { return len(*s.entries.Load()) }

// Replace sets the known tokens to those of other.
func (s *Store) Replace(other *Store) { s.entries.Store(other.entries.Load()) }

// Lookup returns the label of token, or false if it is unknown. All known hashes are compared
// in constant time, so the duration does not tell which (or whether a) token matched.
func (s *Store) Lookup(token string) (string, bool) {
	if len(token) < MinTokenLength || len(token) > MaxTokenLength {
		return "", false
	}
	h := sha256.Sum256([]byte(token))
	label, found := "", 0
	for _, e := range *s.entries.Load() {
		if subtle.ConstantTimeCompare(h[:], e.hash[:]) == 1 {
			label = e.label
			found = 1
		}
	}
	return label, found == 1
}

// Parse reads a token file.
func Parse(r io.Reader) (*Store, error) {
	var entries []entry
	labels := map[string]bool{}
	sc := bufio.NewScanner(r)
	line := 0
	for sc.Scan() {
		line++
		text := strings.TrimSpace(sc.Text())
		if i := strings.IndexByte(text, '#'); i >= 0 {
			text = strings.TrimSpace(text[:i])
		}
		if text == "" {
			continue
		}
		fields := strings.Fields(text)
		if len(fields) != 2 {
			return nil, fmt.Errorf("line %d: expected \"<label> sha256:<hex>\"", line)
		}
		label, hashText := fields[0], fields[1]
		if !reLabel.MatchString(label) {
			return nil, fmt.Errorf("line %d: invalid label (allowed: A-Z a-z 0-9 . _ -, at most 32)", line)
		}
		if labels[label] {
			return nil, fmt.Errorf("line %d: duplicate label %q", line, label)
		}
		hexText, ok := strings.CutPrefix(hashText, "sha256:")
		if !ok {
			// Never echo the value: it might be a plain token pasted by mistake.
			return nil, fmt.Errorf("line %d: hash must start with \"sha256:\" (store hashes, not tokens)", line)
		}
		raw, err := hex.DecodeString(hexText)
		if err != nil || len(raw) != sha256.Size {
			return nil, fmt.Errorf("line %d: hash must be 64 hex digits", line)
		}
		e := entry{label: label}
		copy(e.hash[:], raw)
		entries = append(entries, e)
		labels[label] = true
	}
	if err := sc.Err(); err != nil {
		return nil, err
	}
	s := &Store{}
	s.entries.Store(&entries)
	return s, nil
}

// Load reads a token file from disk.
func Load(path string) (*Store, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	s, err := Parse(f)
	if err != nil {
		return nil, fmt.Errorf("%s: %w", path, err)
	}
	return s, nil
}

// ErrNoToken is returned by BearerToken if the request has no Bearer token.
var ErrNoToken = errors.New("no bearer token")

// BearerToken returns the token of the Authorization header ("Bearer <token>").
func BearerToken(r *http.Request) (string, error) {
	h := r.Header.Get("Authorization")
	scheme, token, ok := strings.Cut(h, " ")
	if !ok || !strings.EqualFold(scheme, "Bearer") {
		return "", ErrNoToken
	}
	token = strings.TrimSpace(token)
	if token == "" {
		return "", ErrNoToken
	}
	return token, nil
}

// HashLine returns the token file line for token.
func HashLine(label, token string) string {
	h := sha256.Sum256([]byte(token))
	return label + " sha256:" + hex.EncodeToString(h[:])
}

// NewToken returns a random token (256 bits, URL-safe base64 without padding).
func NewToken() (string, error) {
	b := make([]byte, 32)
	if _, err := rand.Read(b); err != nil {
		return "", err
	}
	return base64.RawURLEncoding.EncodeToString(b), nil
}

// ValidLabel reports whether label can be used in a token file.
func ValidLabel(label string) bool { return reLabel.MatchString(label) }
